#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::Matrix<DT, 1, 2> B;

    heartlib(const double & a)
    {

        // B = [ a I ]
        Eigen::Matrix<DT, 1, 2> B_0;
        B_0 << a, 1;
        B = B_0;
    }
};

