function output = heartlib(a)
% output = heartlib(a)
%
%    B = [ a I ]
%            where
%            a: ℝ: a scalar
    assert(numel(a) == 1);

    % B = [ a I ]

    B_0 = zeros(1, 2);
    B_0(1,:) = [a, 1];
    B = B_0;
    output.B = B;
end

